1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which instantiations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. A handle is also what tells one instantiation from
9	//! another while a type is being expanded (`Box<Box<string>>` is two instantiations of one declaration): only its
10	//! equality is read, inside one conversion, so the answer does not depend on the numbers. The recursion marker that
11	//! results is named by the declaration (the alias or interface) and holds no handle. The memo is keyed by the enclosing
12	//! instantiations a conversion actually asked about, not by all of them (see [`State::memo`]).
13	//!
14	//! Every descent into the parts of a type (members, properties, elements, holes) passes [`Converter::enter`], which
15	//! decides before anything is fetched or converted whether the type is an enclosing instantiation (a back-reference),
16	//! sits too deep, or is too wide.
17	//!
18	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
19	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
20	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
21	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type, unless it is
22	//! wider than the budget and what it applies to has a name (see [`Converter::over_budget`]). A dependency's union of
23	//! literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
24	//! [`PropType::Truncated`], never the checker's text standing in as a name. The width of an object counts only the
25	//! members the project did not declare: its own are listed whole.
26	
27	use std::future::Future;
28	use std::pin::Pin;
29	use std::sync::atomic::{AtomicU64, Ordering};
30	use std::sync::{Arc, Mutex};
31	
32	use caliper_docgen_core::react_types::{html_element_for, html_element_from_type_arg, is_intrinsic_tag};
33	use caliper_docgen_core::types::semantic::{SemanticProp, degraded_type, unresolved_type};
34	use caliper_docgen_core::types::{
35	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
36	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
37	};
38	use rustc_hash::FxHashMap;
39	
40	use crate::declared::Declared;
41	use crate::printed::{Marker, SignatureMarkers, signature_markers, tuple_labels};
42	use crate::rpc::{
43	    CallError, CompactSymbol, IndexInfo, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, SymbolRef,
44	    TypeInfo, decode, flag,
45	};
46	use serde_json::value::RawValue;
47	
48	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
49	const MAX_DEPTH: u8 = 5;
50	/// The most properties an object type lists at the top (a prop's own type) and below it that the project did not declare
51	/// itself (see [`is_own`]): what it declared is never cut.
52	const MAX_FIELDS: [usize; 2] = [100, 40];
53	/// The most members a union or intersection lists at the top and below it.
54	const MAX_MEMBERS: [usize; 2] = [500, 120];
55	/// The most types one converted type holds, itself and every type inside it counted ([`past_size_budget`]): a type with
56	/// more is cut with [`TruncationLimit::Depth`] where it is converted, and the memo keeps the cut form. The caps above
57	/// bound each object, union and intersection, but not what the project declared itself (see [`is_own`]), so a style
58	/// system in the project's own source (Chakra's `SystemStyleObject`: about 700 properties, each a value or an object
59	/// of 130 conditions) expanded to 25 MB of JSON per prop and 42 GB of memory for one extract.
60	///
61	/// What is enforced is this count (18,724 types), not a byte size. It is chosen so that no type under 256 KiB of JSON
62	/// is ever cut: a type in the output is a JSON object with at least a `kind` (`{"kind":"any"}`, 14 bytes, is the
63	/// smallest), so a type of more than this many types is more than 256 KiB. On real projects a type averages about 40
64	/// bytes, so the cut falls near 0.75 MB of JSON: Chakra's largest prop type left whole is 732 KB. The largest prop
65	/// type of Mantine's core is 196 KB; Chakra's style props were 25 MB. The cut is reported as a depth truncation, since
66	/// a limit kind of its own would change the output schema.
67	const MAX_SIZE: usize = 256 * 1024 / MIN_TYPE_BYTES;
68	/// The fewest bytes one type takes in the JSON output: `{"kind":"any"}`.
69	const MIN_TYPE_BYTES: usize = 14;
70	// One type past the budget is more than 256 KiB.
71	const _: () = assert!((MAX_SIZE + 1) * MIN_TYPE_BYTES > 256 * 1024);
72	/// How many of React's tag names (see [`is_tag`]) a union has to list to be React's `ElementType` (`JSX.IntrinsicElements`
73	/// has over 170): the tag names are the one part of it that no declaration identifies.
74	const MIN_INTRINSIC_TAGS: usize = 100;
75	/// The lib's utility aliases that keep the properties of the type they are applied to, and so can stand for it.
76	const UTILITIES: [&str; 5] = ["Omit", "Pick", "Partial", "Required", "Readonly"];
77	
78	/// What a descent found at [`Converter::enter`].
79	enum Gate<T> {
80	    /// The type is not expanded: it is a back-reference, or a cap cut it.
81	    Stop(PropType),
82	    /// The parts of the type, and the context to convert them in.
83	    Open { parts: T, inner: Cx },
84	}
85	
86	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
87	
88	/// What an object's members are known as when its type is entered.
89	enum Listed {
90	    /// The checker was asked for them.
91	    Members(ObjectMembers),
92	    /// How many properties an earlier map over the same keys had, none of them the project's (see [`State::maps`]). It
93	    /// is only handed out where that is more than the budget allows, so the type is cut and no list is needed.
94	    Counted(usize),
95	}
96	
97	/// What [`Converter::over_budget`] reads of the members of an object it cuts.
98	struct Excess {
99	    /// The type has call or construct signatures.
100	    signatures: bool,
101	    /// How many of its properties the project did not declare.
102	    outside: usize,
103	    /// The properties the project declared.
104	    own: Vec<SymbolInfo>,
105	    indexes: Vec<IndexInfo>,
106	}
107	
108	impl Excess {
109	    fn of(members: ObjectMembers) -> Self {
110	        let ObjectMembers { calls, constructs, properties, indexes } = members;
111	        let (own, outside): (Vec<SymbolInfo>, Vec<SymbolInfo>) = properties.into_iter().partition(is_own);
112	        Excess { signatures: !calls.is_empty() || !constructs.is_empty(), outside: outside.len(), own, indexes }
113	    }
114	
115	    fn counted(outside: usize) -> Self {
116	        Excess { signatures: false, outside, own: Vec::new(), indexes: Vec::new() }
117	    }
118	}
119	
120	/// What a map is remembered by: its constraint, as the checker's type handle, and the symbol that declares it.
121	type MapKey = (u64, CompactSymbol);
122	
123	/// The key of a mapped type whose property count another map over the same keys can answer for: one no name stands for
124	/// (an alias's arguments, `Partial<A>`, are what its properties come from, and the key holds none), with no `as` clause
125	/// (which would rename the keys).
126	fn map_key(info: &TypeInfo, origin: Option<&Origin>) -> Option<MapKey> {
127	    if origin.is_some() || info.object_flags & flag::OBJECT_MAPPED == 0 || info.name_type.is_some() {
128	        return None;
129	    }
130	    Some((info.constraint_type?, info.symbol.clone()?))
131	}
132	
133	/// The number of properties of a map's listed members to remember, when the cut of another map over the same keys needs
134	/// no more of them: the project declared none, so none is listed, and the map has no signature and no index signature,
135	/// whose types are another map's own.
136	fn settled_count(members: &ObjectMembers) -> Option<usize> {
137	    let bare = members.calls.is_empty() && members.constructs.is_empty() && members.indexes.is_empty();
138	    (bare && members.properties.iter().all(|property| !is_own(property))).then_some(members.properties.len())
139	}
140	
141	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
142	/// checker's type handle) enclose it, outermost first.
143	#[derive(Debug, Clone, Default)]
144	pub(crate) struct Cx {
145	    depth: u8,
146	    enclosing: Arc<Vec<u64>>,
147	    /// The conversion this context belongs to, which records which enclosing instantiations it asks about. `None` at
148	    /// the roots.
149	    frame: Option<Arc<Frame>>,
150	}
151	
152	/// What one conversion has asked of the instantiations enclosing it, kept to build its memo entry (see
153	/// [`State::memo`]).
154	#[derive(Debug)]
155	struct Frame {
156	    /// How many instantiations enclosed the type when its conversion began: those below this are the outer context, the
157	    /// rest were opened by the conversion itself.
158	    base: usize,
159	    asked: Mutex<Asked>,
160	}
161	
162	#[derive(Debug, Default)]
163	struct Asked {
164	    /// The handles this conversion's own gate compared against its enclosing instantiations.
165	    ids: Vec<u64>,
166	    /// The sets asked by the conversions of its parts, each with the instantiations this conversion had opened by then:
167	    /// those were answered inside it and do not depend on its outer context.
168	    parts: Vec<(Arc<[u64]>, Vec<u64>)>,
169	}
170	
171	impl Frame {
172	    fn new(base: usize) -> Self {
173	        Frame { base, asked: Mutex::default() }
174	    }
175	
176	    fn lock(&self) -> std::sync::MutexGuard<'_, Asked> {
177	        self.asked.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
178	    }
179	
180	    fn ask(&self, id: u64) {
181	        self.lock().ids.push(id);
182	    }
183	
184	    /// A part of this conversion was converted (or recalled) under `enclosing`, having asked about `asked`.
185	    fn absorb(&self, asked: &Arc<[u64]>, enclosing: &[u64]) {
186	        if !asked.is_empty() {
187	            self.lock().parts.push((asked.clone(), enclosing.get(self.base..).unwrap_or_default().to_vec()));
188	        }
189	    }
190	
191	    /// Every handle the conversion asked about whose answer came from outside it: sorted, once each.
192	    fn finish(&self) -> Arc<[u64]> {
193	        let asked = self.lock();
194	        let mut ids = asked.ids.clone();
195	        for (part, opened) in &asked.parts {
196	            ids.extend(part.iter().copied().filter(|id| !opened.contains(id)));
197	        }
198	        ids.sort_unstable();
199	        ids.dedup();
200	        ids.into()
201	    }
202	}
203	
204	impl Cx {
205	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
206	    /// and passes [`Converter::enter`] if it has parts.
207	    fn argument(&self) -> Cx {
208	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone(), frame: self.frame.clone() }
209	    }
210	
211	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
212	    /// only a name can be pointed back to.
213	    fn below(&self, instance: Option<u64>) -> Cx {
214	        let mut enclosing = self.enclosing.clone();
215	        if let Some(id) = instance
216	            && !enclosing.contains(&id)
217	        {
218	            let mut grown = (*enclosing).clone();
219	            grown.push(id);
220	            enclosing = Arc::new(grown);
221	        }
222	        Cx { depth: self.depth.saturating_add(1), enclosing, frame: self.frame.clone() }
223	    }
224	
225	    /// Whether `id` is an instantiation being expanded around the type. The conversion in progress is recorded to have
226	    /// asked, whichever the answer.
227	    fn encloses(&self, id: u64) -> bool {
228	        if let Some(frame) = &self.frame {
229	            frame.ask(id);
230	        }
231	        self.enclosing.contains(&id)
232	    }
233	
234	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
235	        limits[usize::from(self.depth > 0).min(N - 1)]
236	    }
237	}
238	
239	/// What declares a type: the alias it was written through, else its interface or class.
240	#[derive(Debug, Clone)]
241	struct Origin {
242	    name: String,
243	    /// The declaring file as the checker keys it (lower-cased path).
244	    file: String,
245	    alias: bool,
246	}
247	
248	impl Origin {
249	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
250	        let declaration = symbol.declarations.first().map(String::as_str);
251	        Origin {
252	            name: symbol.name.clone(),
253	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
254	            alias,
255	        }
256	    }
257	
258	    fn in_dependency(&self) -> bool {
259	        file_in_dependency(&self.file)
260	    }
261	
262	    fn in_lib(&self) -> bool {
263	        file_in_lib(&self.file)
264	    }
265	
266	    fn in_react(&self) -> bool {
267	        self.file.contains("/@types/react/")
268	    }
269	
270	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
271	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
272	    fn is_boundary(&self) -> bool {
273	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
274	        if self.in_lib() { !self.alias } else { self.in_dependency() }
275	    }
276	
277	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
278	    /// `ReactElement` and `JSX.Element` are not `ReactNode`, which also admits strings, numbers and `null`: they keep
279	    /// their names ([`Self::name`]).
280	    fn react_terminal(&self) -> Option<PropType> {
281	        if !self.in_react() {
282	            return None;
283	        }
284	        match (self.name.as_str(), self.alias) {
285	            ("ReactNode", true) => Some(PropType::ReactNode),
286	            ("ElementType", true) => Some(PropType::ElementType),
287	            ("CSSProperties", false) => Some(PropType::CssProperties),
288	            _ => None,
289	        }
290	    }
291	
292	    /// The name a reference to the type is given. React's `JSX.Element` is named through its namespace: the checker's
293	    /// `Element` is also the DOM's (which `@types/react` declares empty in `global.d.ts` for a program without it).
294	    fn name(&self) -> String {
295	        if self.in_react() && !self.alias && self.name == "Element" && !self.file.ends_with("/global.d.ts") {
296	            return "JSX.Element".to_string();
297	        }
298	        self.name.clone()
299	    }
300	}
301	
302	/// Whether a union member is a tag of React's `JSX.IntrinsicElements`: a string literal (not an enum member) whose value
303	/// that table lists. A literal the checker gave no value for is not one, so it is kept beside the terminal.
304	fn is_tag(member: &TypeInfo) -> bool {
305	    member.flags & flag::STRING_LITERAL != 0
306	        && member.flags & flag::ENUM_LITERAL == 0
307	        && member.value.as_ref().and_then(|value| value.as_str()).is_some_and(is_intrinsic_tag)
308	}
309	
310	/// Whether the checker states the base types of this type in its own terms: the declaration of a class or interface
311	/// does. An instantiation of a generic one (`Box<string>`, only a reference) does not state them in terms of its
312	/// arguments, so a traversal that keeps the arguments cannot list what it inherits; one that wants only names reads the
313	/// generic type instead ([`Converter::named_bases`]).
314	fn states_bases(info: &TypeInfo) -> bool {
315	    info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE) != 0
316	}
317	
318	/// Where the base types of a type are to be asked, from what the checker says of the type itself.
319	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
320	enum BasesOf {
321	    /// A class or interface declaration: the checker states them ([`states_bases`]).
322	    Itself,
323	    /// An instantiation of a generic type: its generic target states them.
324	    Generic,
325	    /// An object type no class or interface declares (a type literal, a mapped type): it has none.
326	    None,
327	    /// A union, a type parameter or any other type the checker was not asked about: whether it has bases is not known.
328	    Unknown,
329	}
330	
331	impl BasesOf {
332	    fn of(info: &TypeInfo) -> Self {
333	        if states_bases(info) {
334	            Self::Itself
335	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
336	            Self::Generic
337	        } else if info.flags & flag::OBJECT != 0 {
338	            Self::None
339	        } else {
340	            Self::Unknown
341	        }
342	    }
343	}
344	
345	fn file_in_dependency(file: &str) -> bool {
346	    file.contains("/node_modules/")
347	}
348	
349	fn file_in_lib(file: &str) -> bool {
350	    let name = file.rsplit('/').next().unwrap_or("");
351	    name.starts_with("lib.") && name.ends_with(".d.ts")
352	}
353	
354	/// Whether a property is the project's own: its first declaration is in a file of the project, not a dependency or the
355	/// lib. A property with no declaration (a mapped type's synthetic one) is not, so a wide mapped type is still cut.
356	fn is_own(property: &SymbolInfo) -> bool {
357	    property.declarations.first().is_some_and(|declaration| {
358	        let file = declared_in(declaration);
359	        !file_in_dependency(file) && !file_in_lib(file)
360	    })
361	}
362	
363	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
364	pub(crate) fn declared_in(declaration: &str) -> &str {
365	    declaration.splitn(3, '.').nth(2).unwrap_or("")
366	}
367	
368	/// Whether `converted` holds more than `budget` types, itself and every type inside it counted. Counted on the tree,
369	/// not by serializing it, and only as far as the budget: the walk stops at the first type past it.
370	fn past_size_budget(converted: &PropType, budget: usize) -> bool {
371	    let mut count = 0usize;
372	    let mut pending = vec![converted];
373	    while let Some(ty) = pending.pop() {
374	        count += 1;
375	        if count > budget {
376	            return true;
377	        }
378	        push_inner(ty, &mut pending);
379	    }
380	    false
381	}
382	
383	/// Pushes every type directly inside `ty` onto `pending`: fields and index keys, signatures, arguments, tuple elements
384	/// and template holes.
385	fn push_inner<'a>(ty: &'a PropType, pending: &mut Vec<&'a PropType>) {
386	    match ty {
387	        PropType::String
388	        | PropType::Number
389	        | PropType::Boolean
390	        | PropType::Null
391	        | PropType::Undefined
392	        | PropType::Any
393	        | PropType::Never
394	        | PropType::Unknown
395	        | PropType::Void
396	        | PropType::BigInt
397	        | PropType::StringLiteral(_)
398	        | PropType::NumberLiteral(_)
399	        | PropType::BoolLiteral(_)
400	        | PropType::BigIntLiteral(_)
401	        | PropType::UniqueSymbol { .. }
402	        | PropType::EnumMember { .. }
403	        | PropType::Truncated { .. }
404	        | PropType::ReactNode
405	        | PropType::CssProperties
406	        | PropType::Ref { .. }
407	        | PropType::ElementType
408	        | PropType::HtmlAttributes { .. }
409	        | PropType::LiteralUnion { .. }
410	        | PropType::SxProps
411	        | PropType::Opaque(_) => {}
412	        PropType::TemplateLiteral(parts) => pending.extend(parts.iter().filter_map(|part| match part {
413	            TemplatePart::Text(_) => None,
414	            TemplatePart::Type(ty) => Some(ty),
415	        })),
416	        PropType::Union(members)
417	        | PropType::Intersection(members)
418	        | PropType::Named { args: members, .. }
419	        | PropType::Recursive { args: members, .. } => pending.extend(members),
420	        PropType::Array(inner) | PropType::Readonly(inner) => pending.push(inner),

