425	                pending.extend(signature.params.iter().map(|param| &param.param_type));
426	                pending.push(&signature.return_type);
427	            }
428	            push_fields(fields, pending);
429	        }
430	        PropType::Function { params, return_type, .. } => {
431	            pending.extend(params.iter().map(|param| &param.param_type));
432	            pending.push(return_type);
433	        }
434	    }
435	}
