447	/// A hash of everything in `ty` that tells most types apart: each type's kind, how many types it holds directly, and its
448	/// names, texts and values. What it leaves out (a field's flags, a tuple's labels) only puts more types in one bucket of
449	/// [`Trees`], which tells them apart by equality. `None` for a type holding a number that equality cannot vouch for:
450	/// NaN equals nothing, and `-0` equals `0` but is written apart.
451	fn fingerprint(ty: &PropType) -> Option<u64> {
452	    use std::hash::{Hash, Hasher};
453	    let mut hasher = rustc_hash::FxHasher::default();
454	    let mut pending = vec![ty];
455	    while let Some(ty) = pending.pop() {
456	        std::mem::discriminant(ty).hash(&mut hasher);
457	        match ty {
458	            PropType::String
459	            | PropType::Number
460	            | PropType::Boolean
461	            | PropType::Null
462	            | PropType::Undefined
463	            | PropType::Any
464	            | PropType::Never
465	            | PropType::Unknown
466	            | PropType::Void
467	            | PropType::BigInt
468	            | PropType::ReactNode
469	            | PropType::CssProperties
470	            | PropType::Ref { .. }
471	            | PropType::ElementType
472	            | PropType::HtmlAttributes { .. }
473	            | PropType::LiteralUnion { .. }
474	            | PropType::SxProps
475	            | PropType::Opaque(_)
476	            | PropType::TemplateLiteral(_)
477	            | PropType::Union(_)
478	            | PropType::Intersection(_)
479	            | PropType::Array(_)
480	            | PropType::Readonly(_)
481	            | PropType::Tuple(_)
482	            | PropType::Function { .. } => {}
483	            PropType::StringLiteral(text) => text.hash(&mut hasher),
484	            PropType::UniqueSymbol { name } => name.hash(&mut hasher),
485	            PropType::NumberLiteral(number) => vouched(*number)?.hash(&mut hasher),
486	            PropType::BoolLiteral(value) => value.hash(&mut hasher),
487	            PropType::BigIntLiteral(value) => value.as_str().hash(&mut hasher),
488	            PropType::EnumMember { enum_name, member, value } => {
489	                enum_name.hash(&mut hasher);
490	                member.hash(&mut hasher);
491	                match value {
492	                    EnumMemberValue::String(text) => text.hash(&mut hasher),
493	                    EnumMemberValue::Number(number) => vouched(*number)?.hash(&mut hasher),
494	                }
495	            }
496	            PropType::Truncated { text, .. } => text.hash(&mut hasher),
497	            PropType::Named { name, .. } | PropType::Recursive { name, .. } => name.hash(&mut hasher),
498	            PropType::Object(fields) | PropType::Callable { fields, .. } => {
499	                fields.iter().for_each(|field| field.name.hash(&mut hasher));
500	            }
501	        }
502	        let before = pending.len();
503	        push_inner(ty, &mut pending);
504	        (pending.len() - before).hash(&mut hasher);
505	    }
506	    Some(hasher.finish())
507	}
