567	/// Everything a component's prop is made of ([`crate::component::props_of_type`]): its property's name, optionality and
568	/// declarations, the symbol it is a member of (its JSDoc's key when it has no declaration: the symbol itself), its type's
569	/// handle, and which of its JSDoc the component asks for. Two props of one snapshot with equal keys are the same prop: the
570	/// type is converted from the handle alone at the top ([`Converter::convert_roots`]), and where it is declared and its
571	/// JSDoc are read from the declarations, the parent and the symbol alone ([`crate::declared`]). Chakra's components
572	/// share a thousand style props, each a union converted from the same handle, so a component after the first finds
573	/// them here and neither converts, copies nor interns them again.
574	///
575	/// The key borrows what it is made of from the property: most props are found kept, and only one that is not is copied,
576	/// into the [`KeptKey`] it is kept by.
577	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
578	pub(crate) struct PropKey<'a> {
579	    hash: u64,
580	    name: &'a str,
581	    optional: bool,
582	    type_id: u64,
583	    declarations: &'a [String],
584	    parent: Option<&'a CompactSymbol>,
585	    /// The symbol's reference, only for a property with no declaration.
586	    symbol: Option<&'a str>,
587	    description: bool,
588	    tags: bool,
589	}
