591	impl<'a> PropKey<'a> {
592	    pub(crate) fn of(property: &'a SymbolInfo, prop_type: &TypeInfo, description: bool, tags: bool) -> Self {
593	        use std::hash::{Hash, Hasher};
594	        let optional = property.flags & flag::SYMBOL_OPTIONAL != 0;
595	        let symbol = property.declarations.is_empty().then(|| property.reference.text());
596	        let parent = property.parent.as_ref();
597	        let mut hasher = rustc_hash::FxHasher::default();
598	        (&property.name, optional, prop_type.id, &property.declarations, parent, symbol, description, tags)
599	            .hash(&mut hasher);
600	        PropKey {
601	            hash: hasher.finish(),
602	            name: &property.name,
603	            optional,
604	            type_id: prop_type.id,
605	            declarations: &property.declarations,
606	            parent,
607	            symbol,
608	            description,
609	            tags,
610	        }
611	    }
612	
613	    /// Whether `kept` was made from what this key names.
614	    fn names(&self, kept: &KeptKey) -> bool {
615	        self.name == kept.name
616	            && self.optional == kept.optional
617	            && self.type_id == kept.type_id
618	            && self.declarations == kept.declarations.as_slice()
619	            && self.parent == kept.parent.as_ref()
620	            && self.symbol == kept.symbol.as_deref()
621	            && self.description == kept.description
622	            && self.tags == kept.tags
623	    }
624	
625	    fn to_kept(self) -> KeptKey {
626	        KeptKey {
627	            name: self.name.to_string(),
628	            optional: self.optional,
629	            type_id: self.type_id,
630	            declarations: self.declarations.to_vec(),
631	            parent: self.parent.cloned(),
632	            symbol: self.symbol.map(str::to_string),
633	            description: self.description,
634	            tags: self.tags,
635	        }
636	    }
637	}
