732	    /// A converter for each program of one session, their memos holding each converted type once between them. The
733	    /// trees go when the last of the converters does.
734	    pub(crate) fn lanes(programs: &[Arc<Rpc>], reverse: bool) -> Vec<Self> {
735	        let trees = Arc::new(Trees::default());
736	        programs
737	            .iter()
738	            .map(|rpc| Self {
739	                rpc: rpc.clone(),
740	                state: Arc::new(State { trees: trees.clone(), ..State::default() }),
741	                reverse,
742	            })
743	            .collect()
744	    }
