746	    /// The type of each symbol of a component's props, in order: those asked about before in this snapshot from what
747	    /// the checker answered then, shared, and the others in one request. Only the props' own symbols go through it: a
748	    /// component lists most of an earlier one's, while the members of the types inside a prop rarely repeat.
749	    pub(crate) async fn types_of_symbols(&self, symbols: &[&SymbolRef]) -> Result<Vec<Arc<TypeInfo>>, CallError> {
750	        let mut types: Vec<Option<Arc<TypeInfo>>> = {
751	            let known = self.state.symbol_types.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
752	            symbols.iter().map(|symbol| known.by_symbol.get(symbol.text()).cloned()).collect()
753	        };
754	        let unknown: Vec<&SymbolRef> =
755	            symbols.iter().zip(&types).filter(|(_, known)| known.is_none()).map(|(symbol, _)| *symbol).collect();
756	        if !unknown.is_empty() {
757	            let answered = self.rpc.types_of_symbols(&unknown).await?;
758	            if answered.len() != unknown.len() {
759	                return Err(CallError::Rejected(format!(
760	                    "getTypesOfSymbols answered {} types for {} symbols",
761	                    answered.len(),
762	                    unknown.len()
763	                )));
764	            }
765	            let mut known = self.state.symbol_types.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
766	            let mut answered = answered.into_iter();
767	            for (symbol, slot) in symbols.iter().zip(&mut types) {
768	                if slot.is_none()
769	                    && let Some(info) = answered.next()
770	                {
771	                    let shared = known.by_id.entry(info.id).or_insert_with(|| Arc::new(info)).clone();
772	                    known.by_symbol.insert(Box::from(symbol.text()), shared.clone());
773	                    *slot = Some(shared);
774	                }
775	            }
776	        }
777	        Ok(types.into_iter().flatten().collect())
778	    }
