780	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
781	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
782	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
783	        let order: Box<dyn Iterator<Item = usize> + Send> =
784	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
785	        for index in order {
786	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
787	                *slot = Some(self.convert(info, cx).await?);
788	            }
789	        }
790	        Ok(slots.into_iter().flatten().collect())
791	    }
