831	    /// The `@types/react` types a props type is made of, by name, in the order it names them: its bases and the members
832	    /// of an intersection, seen through the project's and dependencies' own types and through a lib utility (`Omit`,
833	    /// `Pick`) to what it applies to. A React type is found by where it is declared, as [`Origin::react_terminal`]
834	    /// finds React's terminals, and is not looked into. `None` when a type on the way has bases the checker cannot be
835	    /// asked for ([`Self::named_bases`]): the list would not be the answer, and an empty one would say there are none.
836	    ///
837	    /// The same walk finds the interfaces and classes the props type reaches whole (the second of the pair), each by
838	    /// name and file as the checker keys it: those every member of which can reach the component. It is an allow-list.
839	    /// A type is reached whole only through the edges that keep every member: the props type itself, an intersection's
840	    /// members, a class's or interface's bases (a generic one's through its target), and the lib's own `Partial`,
841	    /// `Required`, `Readonly` and `Omit` (named by the lib's alias: `Omit` only removes keys, and the members left are
842	    /// the answer's props). A lib `Pick` selects: what it applies to is reached, but not whole, and stays so however
843	    /// else it is reached. Any other type is not looked into: a mapped type, a project alias of one (TypeScript names
844	    /// the type by the outermost alias, and the lib writes `Omit` as a `Pick`, so under a project alias the two cannot
845	    /// be told apart), a conditional, a union. What it holds is not proven to reach whole, and the merge does not
846	    /// collapse it (`SemanticComponent::whole`).
847	    pub(crate) async fn composes(
848	        &self,
849	        props_type: &TypeInfo,
850	    ) -> Result<(Option<Vec<String>>, Vec<(String, String)>), CallError> {
851	        let mut names: Vec<String> = Vec::new();
852	        let mut reached: Vec<(String, String)> = Vec::new();
853	        let mut selected: Vec<(String, String)> = Vec::new();
854	        let mut known = true;
855	        let mut seen: Vec<(u64, bool)> = Vec::new();
856	        // Each type with whether every edge on the way to it keeps every member.
857	        let mut pending = vec![(props_type.clone(), true)];
858	        while let Some((info, whole)) = pending.pop() {
859	            if seen.contains(&(info.id, whole)) {
860	                continue;
861	            }
862	            seen.push((info.id, whole));
863	            let origin = self.origin(&info).await?;
864	            if let Some(origin) = &origin {
865	                if origin.in_react() {
866	                    if !names.contains(&origin.name) {
867	                        names.push(origin.name.clone());
868	                    }
869	                    continue;
870	                }
871	                if origin.alias && origin.in_lib() && UTILITIES.contains(&origin.name.as_str()) {
872	                    let keeps = whole && origin.name != "Pick";
873	                    let applied = self.rpc.alias_type_arguments(info.id).await?.into_iter().take(1);
874	                    pending.extend(applied.map(|base| (base, keeps)));
875	                    continue;
876	                }
877	            }
878	            // A class or interface, or an instantiation of one: a source a prop's `parent` can name.
879	            if info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0
880	                && let Some(source) = self.symbol_origin(&info).await?
881	            {
882	                let into = if whole { &mut reached } else { &mut selected };
883	                let key = (source.name, source.file);
884	                if !into.contains(&key) {
885	                    into.push(key);
886	                }
887	            }
888	            let parts = if info.flags & flag::INTERSECTION != 0 {
889	                self.parts(info.id, Parts::Members).await?
890	            } else {
891	                let Some(bases) = self.named_bases(&info).await? else {
892	                    known = false;
893	                    continue;
894	                };
895	                bases
896	            };
897	            // Last first onto the stack, so they are taken in the order the type names them.
898	            pending.extend(parts.into_iter().rev().map(|part| (part, whole)));
899	        }
900	        reached.retain(|source| !selected.contains(source));
901	        Ok((known.then_some(names), reached))
902	    }
