905	    /// bases of the declaration of a class or interface; an instantiation of a generic one (`Props<string>`, only a
906	    /// reference) has none of its own, so they are read from the generic type it instantiates, which names the same
907	    /// types over its own type parameters. `None` when the checker cannot be asked ([`BasesOf::Unknown`]). A traversal
908	    /// that keeps the arguments of what it finds ([`Self::base_layers`]) cannot read them this way, since
909	    /// `HTMLAttributes<T>` is not `HTMLAttributes<HTMLDivElement>`, and tests [`states_bases`] of the type itself.
910	    async fn named_bases(&self, info: &TypeInfo) -> Result<Option<Vec<TypeInfo>>, CallError> {
911	        match BasesOf::of(info) {
912	            BasesOf::Itself => Ok(Some(self.rpc.base_types(info.id).await?)),
913	            BasesOf::Generic => {
914	                let target = self.rpc.target_of_type(info.id).await?;
915	                match BasesOf::of(&target) {
916	                    BasesOf::Itself => Ok(Some(self.rpc.base_types(target.id).await?)),
917	                    _ => Ok(info.is_tuple_type.then(Vec::new)),
918	                }
919	            }
920	            BasesOf::None => Ok(Some(Vec::new())),
921	            BasesOf::Unknown => Ok(None),
922	        }
923	    }
