925	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
926	        Box::pin(async move {
927	            // A memo hit copies the tree it recalls, and a conversion can build gigabytes of them between two requests.
928	            crate::heap::step()?;
929	            if let Some(entry) = self.recall(info.id, cx) {
930	                self.state.hits.fetch_add(1, Ordering::Relaxed);
931	                if let Some(frame) = &cx.frame {
932	                    frame.absorb(&entry.asked, &cx.enclosing);
933	                }
934	                return Ok(PropType::clone(&entry.converted));
935	            }
936	            self.state.misses.fetch_add(1, Ordering::Relaxed);
937	            let frame = Arc::new(Frame::new(cx.enclosing.len()));
938	            let own = Cx { depth: cx.depth, enclosing: cx.enclosing.clone(), frame: Some(frame.clone()) };
939	            let mut converted = self.uncached(info, &own).await?;
940	            if past_size_budget(&converted, MAX_SIZE) {
941	                let origin = self.origin(info).await?;
942	                converted = self.truncated(info, origin.as_ref(), TruncationLimit::Depth).await?;
943	            }
944	            let asked = frame.finish();
945	            if let Some(parent) = &cx.frame {
946	                parent.absorb(&asked, &cx.enclosing);
947	            }
948	            let enclosed_by = cx.enclosing.iter().copied().filter(|id| asked.binary_search(id).is_ok()).collect();
949	            let entry = Arc::new(Entry { asked, enclosed_by, converted: self.state.trees.share(&converted) });
950	            if let Ok(mut memo) = self.state.memo.lock() {
951	                memo.entry((info.id, cx.depth)).or_default().push(entry);
952	            }
953	            Ok(converted)
954	        })
955	    }
