1452	    async fn object(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
1453	        if info.is_tuple_type {
1454	            return self.tuple(info, cx).await;
1455	        }
1456	        if info.object_flags & flag::OBJECT_REFERENCE != 0
1457	            && let Some(own) = self.symbol_origin(info).await?
1458	            && own.in_lib()
1459	            && !own.alias
1460	            && matches!(own.name.as_str(), "Array" | "ReadonlyArray")
1461	        {
1462	            return self.array(info, own.name == "ReadonlyArray", cx).await;
1463	        }
1464	        let origin = self.origin(info).await?;
1465	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
1466	            return Ok(terminal);
1467	        }
1468	        let boundary = origin.as_ref().filter(|origin| origin.is_boundary());
1469	        // A dependency's interface is a name unless it is callable; its properties are not asked for.
1470	        if let Some(origin) = boundary
1471	            && self.rpc.signatures(info.id, SignatureKind::Call).await?.is_empty()
1472	        {
1473	            return self.named_type(info, origin, cx).await;
1474	        }
1475	        // The width is not counted at the gate: only the members that are not the project's own are, below.
1476	        let key = map_key(info, origin.as_ref());
1477	        let gate = self
1478	            .enter(info, origin.as_ref(), cx, [usize::MAX; 2], || async {
1479	                let Some(key) = key else { return Ok((Listed::Members(self.rpc.object_members(info.id).await?), 0)) };
1480	                if let Some(outside) = self.settled(&key).filter(|outside| *outside > cx.limit(MAX_FIELDS)) {
1481	                    return Ok((Listed::Counted(outside), 0));
1482	                }
1483	                let members = self.rpc.object_members(info.id).await?;
1484	                self.settle(key, info, &members).await;
1485	                Ok((Listed::Members(members), 0))
1486	            })
1487	            .await?;
1488	        let (listed, inner) = match gate {
1489	            Gate::Stop(stopped) => return Ok(stopped),
1490	            Gate::Open { parts, inner } => (parts, inner),
1491	        };
1492	        let members = match listed {
1493	            Listed::Members(members) => members,
1494	            Listed::Counted(outside) => {
1495	                return self.over_budget(info, origin.as_ref(), Excess::counted(outside), cx, &inner).await;
1496	            }
1497	        };
1498	        if let Some(origin) = boundary
1499	            && !members.properties.is_empty()
1500	        {
1501	            return self.named_type(info, origin, cx).await;
1502	        }
1503	        let outside = members.properties.iter().filter(|property| !is_own(property)).count();
1504	        if outside > cx.limit(MAX_FIELDS) {
1505	            return self.over_budget(info, origin.as_ref(), Excess::of(members), cx, &inner).await;
1506	        }
1507	        let ObjectMembers { calls, constructs, properties, indexes } = members;
1508	
1509	        // Which of a signature's parameters are optional is read from the printed type here, and nowhere else.
1510	        let Some(markers) = self.printed_markers(info.id, &calls, &constructs).await? else {
1511	            return self.unreadable_signatures(info.id).await;
1512	        };
1513	        let mut signatures = Vec::with_capacity(calls.len() + constructs.len());
1514	        for (kind, group, printed) in
1515	            [(Kind::Call, &calls, &markers.calls), (Kind::Construct, &constructs, &markers.constructs)]
1516	        {
1517	            for (index, signature) in group.iter().enumerate() {
1518	                let printed = printed.get(index).map(Vec::as_slice);
1519	                let Some((type_params, params, return_type)) = self.signature_parts(signature, printed, &inner).await?
1520	                else {
1521	                    return self.unreadable_signatures(info.id).await;
1522	                };
1523	                signatures.push(CallSignature { kind, type_params, params, return_type });
1524	            }
1525	        }
1526	        if signatures.len() == 1 && calls.len() == 1 && properties.is_empty() && indexes.is_empty() {
1527	            let CallSignature { type_params, params, return_type, .. } = signatures.swap_remove(0);
1528	            return Ok(PropType::Function { type_params, params, return_type: Box::new(return_type) });
1529	        }
1530	        let fields = self.fields(&properties, &indexes, &inner).await?;
1531	        if signatures.is_empty() {
1532	            return Ok(PropType::Object(fields));
1533	        }
1534	        Ok(PropType::Callable { signatures, fields })
