1537	    /// An object with more members from outside the project (inherited from a dependency or the lib) than the budget
1538	    /// lists. What the project declared itself is never cut. The rest stands as what it is named through: the utility
1539	    /// wrapper that built the type (`Omit<HTMLAttributes<HTMLDivElement>, "color">`), or the base types of the interface
1540	    /// or class that inherits it. When neither can be named, the rest is a [`PropType::Truncated`] with the real count.
1541	    async fn over_budget(
1542	        &self,
1543	        info: &TypeInfo,
1544	        origin: Option<&Origin>,
1545	        excess: Excess,
1546	        cx: &Cx,
1547	        inner: &Cx,
1548	    ) -> Result<PropType, CallError> {
1549	        let Excess { signatures, outside, own, indexes } = excess;
1550	        let cut = TruncationLimit::Members { total: to_u32(outside) };
1551	        // A type with signatures is a function with properties: its shape is not a set of fields to split.
1552	        if signatures {
1553	            return self.truncated(info, origin, cut).await;
1554	        }
1555	        if let Some(origin) = origin
1556	            && origin.alias
1557	            && let Some(wrapper) = self.wrapper(info, origin, cx).await?
1558	        {
1559	            return Ok(wrapper);
1560	        }
1561	        // The declaration of a class or interface has base types; an instantiation of a generic one (`Box<string>`, only a
1562	        // reference) does not state them in terms of its arguments, so it is cut.
1563	        let layers = if origin.is_some_and(|origin| !origin.alias) && states_bases(info) {
1564	            self.base_layers(info, cx).await?
1565	        } else {
1566	            None
1567	        };
1568	        let mut parts = Vec::new();
1569	        if !own.is_empty() || !indexes.is_empty() {
1570	            parts.push(PropType::Object(self.fields(&own, &indexes, inner).await?));
1571	        }
1572	        match layers {
1573	            Some(layers) => parts.extend(layers),
1574	            None => parts.push(self.truncated(info, origin, cut).await?),
1575	        }
1576	        Ok(if parts.len() == 1 { parts.swap_remove(0) } else { PropType::Intersection(parts) })
1577	    }
