1579	    /// What a type declared as `interface A extends B, C` stands on: each base type named (see [`Self::layer`]), a base
1580	    /// the project declares seen through to its own bases (its members are the project's own and are listed). `None`
1581	    /// when a base is neither.
1582	    async fn base_layers(&self, info: &TypeInfo, cx: &Cx) -> Result<Option<Vec<PropType>>, CallError> {
1583	        let mut layers: Vec<PropType> = Vec::new();
1584	        let mut pending: Vec<TypeInfo> = self.rpc.base_types(info.id).await?;
1585	        pending.reverse();
1586	        while let Some(base) = pending.pop() {
1587	            if let Some(layer) = self.layer(&base, cx).await? {
1588	                if !layers.contains(&layer) {
1589	                    layers.push(layer);
1590	                }
1591	                continue;
1592	            }
1593	            // A base declared in the project: its members are already among the type's own, and what it inherits is
1594	            // seen through to its own bases. An instantiation of a generic one does not state them, so what it
1595	            // inherits would be missing from the answer: the type is cut instead, with its count.
1596	            let declared_here = match self.origin(&base).await? {
1597	                Some(origin) => !origin.alias && !origin.in_dependency() && !origin.in_lib(),
1598	                None => false,
1599	            };
1600	            if !declared_here || !states_bases(&base) {
1601	                return Ok(None);
1602	            }
1603	            let mut inherited = self.rpc.base_types(base.id).await?;
1604	            inherited.reverse();
1605	            pending.extend(inherited);
1606	        }
1607	        // Members came from somewhere: bases that account for none of them are not an answer.
1608	        Ok((!layers.is_empty()).then_some(layers))
1609	    }
