1699	    async fn tuple(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
1700	        let origin = self.alias_origin(info).await?;
1701	        let gate = self
1702	            .enter(info, origin.as_ref(), cx, MAX_MEMBERS, || async {
1703	                // The reference carries the arguments; the tuple type it instantiates carries how each element is declared.
1704	                let arguments = self.parts(info.id, Parts::Arguments).await?;
1705	                let target = self.rpc.target_of_type(info.id).await?;
1706	                let total = arguments.len();
1707	                Ok(((arguments, target), total))
1708	            })
1709	            .await?;
1710	        let ((arguments, target), inner) = match gate {
1711	            Gate::Stop(stopped) => return Ok(stopped),
1712	            Gate::Open { parts, inner } => (parts, inner),
1713	        };
1714	        let labels = if target.labeled_element_declarations.is_empty() {
1715	            None
1716	        } else {
1717	            tuple_labels(&self.display(info.id).await?, arguments.len())
1718	        };
1719	        let element_types = self.convert_all(&arguments, &inner).await?;
1720	        let mut elements = Vec::with_capacity(arguments.len());
1721	        for (index, element_type) in element_types.into_iter().enumerate() {
1722	            let element_flags = target.element_flags.get(index).copied().unwrap_or(1);
1723	            let kind = if element_flags & flag::ELEMENT_VARIADIC != 0 {
1724	                TupleElementKind::Variadic
1725	            } else if element_flags & flag::ELEMENT_REST != 0 {
1726	                TupleElementKind::Rest
1727	            } else if element_flags & flag::ELEMENT_OPTIONAL != 0 {
1728	                TupleElementKind::Optional
1729	            } else {
1730	                TupleElementKind::Required
1731	            };
1732	            let label = labels.as_ref().and_then(|labels| labels.get(index)).and_then(|label| TupleLabel::new(label));
1733	            // An optional element's type argument includes the `undefined` of leaving it out.
1734	            let element_type = without_undefined(element_type, kind == TupleElementKind::Optional);
