1741	    async fn fields(
1742	        &self,
1743	        properties: &[SymbolInfo],
1744	        indexes: &[IndexInfo],
1745	        cx: &Cx,
1746	    ) -> Result<Vec<ObjectField>, CallError> {
1747	        let references: Vec<_> = properties.iter().map(|property| &property.reference).collect();
1748	        let (types, readonly) = if references.is_empty() {
1749	            (Vec::new(), Vec::new())
1750	        } else {
1751	            (self.rpc.types_of_symbols(&references).await?, self.rpc.readonly_symbols(&references).await?)
1752	        };
1753	        let converted = self.convert_all(&types, cx).await?;
1754	        let mut fields = Vec::with_capacity(properties.len() + indexes.len());
1755	        for ((property, prop_type), readonly) in properties.iter().zip(converted).zip(readonly) {
1756	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
1757	            let prop_type = without_undefined(prop_type, !required);
1758	            let mut field = ObjectField::new(property_name(&property.name), prop_type, required, String::new());
1759	            field.readonly = readonly;
1760	            fields.push(field);
1761	        }
1762	        let sides: Vec<TypeInfo> =
1763	            indexes.iter().flat_map(|index| [index.key_type.clone(), index.value_type.clone()]).collect();
1764	        let mut sides = self.convert_all(&sides, cx).await?.into_iter();
1765	        for index in indexes {
1766	            let (Some(key), Some(value)) = (sides.next(), sides.next()) else { break };
1767	            let mut field = ObjectField::new("key", value, true, String::new());
1768	            field.readonly = index.is_readonly;
1769	            field.index_key = Some(Box::new(key));
1770	            fields.push(field);
1771	        }
1772	        Ok(fields)
1773	    }
