1798	    /// One signature's type parameters, parameters and return type; `None` when a parameter that is not the rest
1799	    /// parameter has no marker, since whether it is optional is then unknown and is not guessed.
1800	    async fn signature_parts(
1801	        &self,
1802	        signature: &SignatureInfo,
1803	        printed: Option<&[Marker]>,
1804	        cx: &Cx,
1805	    ) -> Result<Option<(Vec<String>, Vec<FunctionParam>, PropType)>, CallError> {
1806	        let parameters = self.rpc.parameters(signature.id).await?;
1807	        let has_rest = signature.flags & flag::SIGNATURE_HAS_REST_PARAMETER != 0;
1808	        // A printed signature that does not give one entry per parameter states none of them.
1809	        let markers = printed.filter(|markers| markers.len() == parameters.len());
1810	        let known_without_markers = usize::from(has_rest);
1811	        if markers.is_none() && parameters.len() > known_without_markers {
1812	            return Ok(None);
1813	        }
1814	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
1815	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
1816	        let converted = self.convert_all(&types, cx).await?;
1817	        let mut params = Vec::with_capacity(parameters.len());
1818	        for (index, (parameter, param_type)) in parameters.iter().zip(converted).enumerate() {
1819	            let marker = markers.and_then(|markers| markers.get(index)).copied().unwrap_or_default();
1820	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
1821	            let optional = marker.optional && !rest;
1822	            let param_type = without_undefined(param_type, optional);
1823	            // A destructured parameter has no name of its own; the checker calls it `__0`.
1824	            let name = (!is_destructured(&parameter.name)).then(|| parameter.name.clone());
1825	            params.push(FunctionParam { name, param_type, optional, rest });
1826	        }
1827	        let return_info = self.rpc.return_type(signature.id).await?;
1828	        let return_type = self.convert(&return_info, cx).await?;
1829	        let mut type_params = Vec::new();
1830	        if !signature.type_parameters.is_empty() {
1831	            for parameter in self.rpc.type_parameters(signature.id).await? {
1832	                match self.rpc.symbol_of_type(parameter.id).await? {
1833	                    Some(symbol) => type_params.push(symbol.name),
1834	                    None => type_params.push(self.display(parameter.id).await?),
1835	                }
1836	            }
1837	        }
1838	        Ok(Some((type_params, params, return_type)))
1839	    }
