#!/bin/zsh
# usage: run.sh <bin-label> <corpus> [extra args...]
# writes $OUT/<corpus>.<label>[.none].json and .err; prints requests, rss, times
bin=/tmp/claude-501/fr/$1
corpus=$2
shift 2
R=/Users/gabe/.cache/caliper/corpora/repos
case $corpus in
  mantine) src=$R/mantine/packages/@mantine/core/src ;;
  chakra) src=$R/chakra-ui/packages/react/src ;;
  shadcn) src=$R/shadcn-ui/apps/v4 ;;
  antd) src=$R/ant-design/components ;;
  spectrum) src=$R/react-spectrum/packages ;;
  *) src=$corpus; corpus=$(basename $corpus) ;;
esac
suffix=""
[[ "$*" == *none* ]] && suffix=".none"
out=/tmp/claude-501/fr/out/$corpus.$1$suffix
mkdir -p /tmp/claude-501/fr/out
/usr/bin/time -l $bin extract --src $src --quiet --no-cache --load-dependencies --json -vv "$@" > $out.json 2> $out.err
code=$?
python3 -I - $out.err $corpus.$1$suffix $code <<'EOF'
import re, sys
text = open(sys.argv[1]).read()
reqs = {}
for line in text.splitlines():
    if "semantic backend finished" in line:
        m = re.search(r'requests=\{(.*?)\}', line)
        if m:
            for k, v in re.findall(r'"(\w+)": (\d+)', m.group(1)):
                reqs[k] = reqs.get(k, 0) + int(v)
rss = re.search(r'(\d+)\s+maximum resident', text)
t = re.search(r'([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys', text)
batch = reqs.get("batchRequests", 0)
total = sum(reqs.values())
top = total - sum(v for k, v in reqs.items() if k in SUBS) if False else None
print(sys.argv[2], "exit", sys.argv[3], "total", total, "rss_mb", int(rss.group(1)) // 2**20 if rss else None,
      "real", t.group(1) if t else None, "cpu", round(float(t.group(2)) + float(t.group(3)), 2) if t else None)
print("  ", sorted(reqs.items(), key=lambda kv: -kv[1])[:14])
EOF

